761	    ///
762	    /// This will ignore styles for tags (conceptually, they just don't exist).
763	    pub fn trunk_from_pairs(iter: &[(&Content, Self)]) -> Option<Self> {
764	        Self::trunk(iter.iter().filter(|(c, _)| !c.is::<TagElem>()).map(|&(_, s)| s))
765	    }
766	}
