955	    fn fold_or(self, outer: Self) -> Self {
956	        match (self, outer) {
957	            (Some(inner), Some(outer)) => Some(inner.fold(outer)),
958	            // If one of values is `None`, return the other one instead of
959	            // folding.
960	            (inner, outer) => inner.or(outer),
961	        }
